<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('clients.view');$pageTitle='Clientes por país';$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$country=trim((string)($_GET['country']??''));$where=[];$params=[];if($q!==''){$where[]='(c.company_name LIKE ? OR c.trade_name LIKE ? OR c.contact_name LIKE ? OR c.email LIKE ? OR c.tax_id LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like);}if(in_array($status,['active','inactive','prospect'],true)){$where[]='c.status=?';$params[]=$status;}if($country!==''){$where[]='COALESCE(NULLIF(c.country,\'\'),\'Sin país\')=?';$params[]=$country;}$whereSql=$where?'WHERE '.implode(' AND ',$where):'';$sql="SELECT c.*,COUNT(s.id) service_count,MIN(CASE WHEN s.status='active' AND s.expiration_date>=CURDATE() THEN s.expiration_date END) next_expiration,SUM(CASE WHEN s.status='active' THEN 1 ELSE 0 END) active_service_count FROM clients c LEFT JOIN client_services s ON s.client_id=c.id {$whereSql} GROUP BY c.id ORDER BY COALESCE(NULLIF(c.country,''),'Sin país') ASC,c.company_name ASC";$stmt=db()->prepare($sql);$stmt->execute($params);$clients=$stmt->fetchAll();$countries=db()->query("SELECT COALESCE(NULLIF(country,''),'Sin país') country_name,COUNT(*) total FROM clients GROUP BY COALESCE(NULLIF(country,''),'Sin país') ORDER BY country_name")->fetchAll();$groups=[];foreach($clients as$c)$groups[$c['country']?:'Sin país'][]=$c;require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Directorio ordenado por país</h2><span class="table-sub"><?=count($clients)?> clientes encontrados en <?=count($groups)?> países o grupos.</span></div><?php if(has_permission('clients.create')):?><a class="btn btn-primary" href="client_form.php">+ NUEVO CLIENTE</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters"><input name="q" value="<?=e($q)?>" placeholder="Buscar empresa, contacto o email"><select name="country"><option value="">Todos los países</option><?php foreach($countries as$row):?><option value="<?=e($row['country_name'])?>" <?=$country===$row['country_name']?'selected':''?>><?=e($row['country_name'])?> (<?=(int)$row['total']?>)</option><?php endforeach;?></select><select name="status"><option value="">Todos los estados</option><option value="active" <?=$status==='active'?'selected':''?>>Activos</option><option value="prospect" <?=$status==='prospect'?'selected':''?>>Prospectos</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactivos</option></select><button class="btn btn-secondary btn-small">Filtrar</button></form></div></section>
<?php if(!$groups):?><section class="panel" style="margin-top:20px"><div class="empty">No se encontraron clientes.</div></section><?php endif;?><?php foreach($groups as$countryName=>$countryClients):?><section class="panel country-group"><div class="country-heading"><h3><?=e($countryName)?></h3><span><?=count($countryClients)?> cliente<?=count($countryClients)===1?'':'s'?></span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Contacto</th><th>Servicios</th><th>Próximo vencimiento</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($countryClients as$client):?><tr><td><a class="table-title" href="client_view.php?id=<?=(int)$client['id']?>"><?=e($client['company_name'])?></a><span class="table-sub"><?=e($client['trade_name']?:$client['city']?:'Sin nombre comercial')?></span></td><td><?=e($client['contact_name']?:'—')?><span class="table-sub"><?=e($client['email']?:$client['whatsapp']?:'')?></span></td><td><strong><?=(int)$client['active_service_count']?></strong> activos<span class="table-sub"><?=(int)$client['service_count']?> registrados</span></td><td><?=e(format_date($client['next_expiration']))?></td><td><span class="badge badge-<?=$client['status']==='active'?'green':($client['status']==='prospect'?'orange':'gray')?>"><?=e(client_status_label($client['status']))?></span></td><td><div class="actions"><a class="btn btn-light btn-small" href="client_view.php?id=<?=(int)$client['id']?>">Ver</a><?php if(has_permission('clients.edit')):?><a class="btn btn-light btn-small" href="client_form.php?id=<?=(int)$client['id']?>">Editar</a><?php endif;?><?php if(has_permission('clients.delete')):?><form method="post" action="client_delete.php" class="inline-form" onsubmit="return confirm(<?=e(json_encode('¿Eliminar definitivamente a '.$client['company_name'].'? Esta acción también puede eliminar información vinculada.',JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT))?>);"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$client['id']?>"><button class="btn btn-danger btn-small" type="submit">Eliminar</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?><?php require __DIR__.'/includes/footer.php';?>
